 window.parseAcademicGroup = function parseAcademicGroup(input) {
  if (!input) return null;
  const str = String(input).trim().toLowerCase();
  
  // Exact single number 1-16 (e.g. "7", " 7 ")
  const bareMatch = str.match(/^([1-9]|1[0-6])$/);
  if (bareMatch) {
    return `جروب ${bareMatch[1]}`;
  }

  // Preceded by group/section indicator:
  // e.g. "جروب 7", "سكشن 5", "مجموعة 3", "group 7", "g7", "sec 4", "أنا في جروب 3", "انا جروب 10"
  const match = str.match(/(?:جروب|سكشن|مجموعة|مجموعتي|group|sec|section|\bg)\s*([1-9]|1[0-6])(?![0-9])/i);
  if (match) {
    const num = parseInt(match[1], 10);
    if (num >= 1 && num <= 16) {
      return `جروب ${num}`;
    }
  }
  return null;
};
 window.getScheduleForGroup = function getScheduleForGroup(groupNameOrNumber) {
  const norm = parseAcademicGroup(groupNameOrNumber) || 'جروب 7';
  return ALL_COLLEGE_GROUPS_SCHEDULE[norm] || ALL_COLLEGE_GROUPS_SCHEDULE['جروب 7'];
};
